export const MONUMENTS = JSON.parse("[{\"id\":\"n7403338327\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"Медикам-балтийцам, павшим в боях за Родину 1941-1945\",\"x\":-4037.8,\"z\":2011.1},{\"id\":\"n11146625409\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3965.1,\"z\":2128.5,\"inscription\":\"1905 - 1930 В этом доме помещался первый союз рабочих резиновой мануфактуры \\\"Красный треугольник\\\", организованный 18-го ноября 1905 г.\"},{\"id\":\"n6516166693\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Пастеру\",\"x\":-3721.5,\"z\":2089.1,\"material\":\"marble\",\"startDate\":\"1971\",\"subject\":\"Q529\",\"inscription\":\"Бывшая Елисаветинская клиническая больница для малолетних детей основана в 1844 году. В 1917 году переименована в детскую больницу имени Пастера. Луи Пастер (1829–1895) — выдающийся французский микробиолог, разработавший учение об инфекции и иммунитете.\"},{\"id\":\"n11964580627\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. А. Климанову\",\"x\":-3300.5,\"z\":2023.7,\"inscription\":\"Здесь в 1888-1893 гг. работал кузнецом революционер Егор Климанов (Афанасьев), активный участник русских социал-демократических организаций. Один из организаторов первой в России маёвки 1891 г.\"},{\"id\":\"n1121883799\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Памятник погибшим сотрудникам Военного порта\",\"x\":-2741.4,\"z\":2141.8,\"inscription\":\"Вечная слава воинам, рабочим и служащим Военного порта — тыла Лен. ВМБ, павшим в боях за свободу и независимость нашей великой Родины (1917–1945 гг.)\"},{\"id\":\"n9603685814\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. И. Чигорину\",\"x\":-2793.6,\"z\":2077.1,\"subject\":\"Q298286\",\"inscription\":\"Здесь с 1901 года по 1907 год жил Михаил Иванович Чигорин, основоположник русской шахматной школы\"},{\"id\":\"n6518666649\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. В. Лебедеву\",\"x\":-5175.8,\"z\":2166.9,\"subject\":\"Q289805\",\"inscription\":\"Здесь, на опытном заводе, с 1930 по 1934 год работал академик Сергей Васильевич Лебедев, основоположник промышленности синтетического каучука, созданной в СССР впервые в мире\"},{\"id\":\"n1117855849\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"name\":\"100-летию подводного флота\",\"x\":-4675.2,\"z\":2155,\"inscription\":\"Морякам-подводникам и кораблестроителям Санкт-Петербурга 1906-2006\"},{\"id\":\"n3688300234\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. С. Лунину\",\"x\":-4701.4,\"z\":2179,\"subject\":\"Q1930354\",\"inscription\":\"В этом доме в 1810-х годах жил декабрист Михаил Сергеевич Лунин, член Союза спасения, Союза благоденствия и Северного общества. В 1845 погиб в акатуйской тюрьме\"}]");
